    Ok(row_uuid) -> {
      let _ = sql.sweep_mark_failed(db, row_uuid, reason_processing_error)
      Nil
    }
    Error(_) -> Nil
  }
  capture(sentry, row_id, reason, "processing error")
  Failed
}
